import sys
from collections import Counter

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    k = int(input[1])
    teams = list(map(int, input[2:]))

    team_sizes = list(Counter(teams).values())
    team_sizes.sort(reverse=True)

    def min_cost(s):
        rides = 0
        i = 0
        while i < len(team_sizes):
            if team_sizes[i] > s:
                return float('inf')
            if i + 1 < len(team_sizes) and team_sizes[i] + team_sizes[i + 1] <= s:
                rides += 1
                i += 2
            else:
                rides += 1
                i += 1
        return rides * s

    low, high = 1, sum(team_sizes)
    result = high
    while low <= high:
        mid = (low + high) // 2
        cost = min_cost(mid)
        if cost < result:
            result = cost
            high = mid - 1
        else:
            low = mid + 1

    print(result)

if __name__ == "__main__":
    main()
